template <typename Iter, typename Pred>
Iter custom_find_if(Iter first, Iter last, Pred p) {
    while (first != last) {
        if (p(*first)) {
            return first;
        }
        ++first;
    }
    return last;
}

struct IsEven {
    bool operator()(int x) const { return x % 2 == 0; }
};

